<?php $p=$product??[];$productGallery=json_decode((string)($p['gallery']??'[]'),true)?:[];if(!empty($p['image'])&&!in_array($p['image'],$productGallery,true))array_unshift($productGallery,$p['image']);$productGallery=array_values(array_unique(array_filter($productGallery,'is_string'))); ?>
<section class="admin-welcome"><div><h1><?= $product?'Modifier le produit':'Ajouter un produit' ?></h1><p>Catalogue, tarifs, disponibilité et galerie.</p></div><a class="btn secondary" href="/admin/produits">← Catalogue</a></section>
<form class="panel admin-editor product-editor" method="post" action="/admin/produits/enregistrer" enctype="multipart/form-data">
<?php if($product): ?><input type="hidden" name="id" value="<?= (int)$p['id'] ?>"><?php endif ?>
<section class="editor-section"><div class="editor-section-title"><span>01</span><div><h3>Présentation commerciale</h3><p>Les informations visibles par vos clients dans la boutique.</p></div></div><div class="field-grid"><label><span class="field-label">Nom du produit <b>*</b></span><input name="name" required value="<?= htmlspecialchars($p['name']??'') ?>" placeholder="Ex. Guide pratique du gérant de station"></label><label><span class="field-label">Type de produit</span><select name="product_type" data-product-type><option value="physical" <?= ($p['product_type']??'physical')==='physical'?'selected':'' ?>>📦 Produit physique</option><option value="digital" <?= ($p['product_type']??'')==='digital'?'selected':'' ?>>↓ Livre / produit numérique</option></select><small>Ce choix adapte automatiquement le stock et la livraison.</small></label><label><span class="field-label">Référence unique</span><input name="reference" value="<?= htmlspecialchars($p['reference']??'') ?>" placeholder="IFMAP-EQP-001"><small>Laissez vide pour une génération automatique.</small></label><label><span class="field-label">Catégorie</span><input name="category" value="<?= htmlspecialchars($p['category']??'Équipements') ?>" placeholder="Livres, mesure, sécurité..."></label><label><span class="field-label">Visibilité</span><select name="status"><option value="draft" <?= ($p['status']??'')==='draft'?'selected':'' ?>>◷ Brouillon — invisible</option><option value="published" <?= ($p['status']??'published')==='published'?'selected':'' ?>>✓ Publié — visible en boutique</option><option value="archived" <?= ($p['status']??'')==='archived'?'selected':'' ?>>○ Archivé</option></select></label><label class="full"><span class="field-label">Description détaillée</span><textarea name="description" rows="7" placeholder="Présentez le produit, son contenu, ses avantages, ses dimensions ou son auteur..."><?= htmlspecialchars($p['description']??'') ?></textarea><small>Une description claire augmente la confiance et facilite l’achat.</small></label></div></section>
<section class="editor-section"><div class="editor-section-title"><span>02</span><div><h3>Tarification et disponibilité</h3><p>Configurez le prix de vente et les règles de disponibilité.</p></div></div><div class="field-grid"><label><span class="field-label">Prix normal</span><div class="input-suffix"><input type="number" min="0" name="price" value="<?= htmlspecialchars($p['price']??'') ?>" placeholder="0"><b>FCFA</b></div></label><label><span class="field-label">Prix promotionnel</span><div class="input-suffix"><input type="number" min="0" name="promotional_price" value="<?= htmlspecialchars($p['promotional_price']??'') ?>" placeholder="Optionnel"><b>FCFA</b></div><small>Il doit rester inférieur au prix normal.</small></label><label data-physical-field><span class="field-label">Disponibilité</span><select name="stock_status"><option value="in_stock" <?= ($p['stock_status']??'')==='in_stock'?'selected':'' ?>>● En stock</option><option value="on_order" <?= ($p['stock_status']??'')==='on_order'?'selected':'' ?>>◷ Sur commande</option><option value="out_of_stock" <?= ($p['stock_status']??'')==='out_of_stock'?'selected':'' ?>>○ Rupture de stock</option></select></label><label data-physical-field><span class="field-label">Quantité initiale</span><input type="number" min="0" name="stock_quantity" value="<?= (int)($p['stock_quantity']??0) ?>" placeholder="0"></label><label data-physical-field><span class="field-label">Seuil d’alerte</span><input type="number" min="0" name="low_stock_threshold" value="<?= (int)($p['low_stock_threshold']??5) ?>"><small>Le dashboard vous avertira à ce niveau.</small></label><label data-physical-field><span class="field-label">Délai indicatif</span><input name="lead_time" value="<?= htmlspecialchars($p['lead_time']??'') ?>" placeholder="Ex. 5 à 7 jours"></label><div class="digital-stock-note full" data-digital-note><span>∞</span><div><strong>Disponibilité illimitée</strong><small>Un produit numérique ne réduit pas le stock physique.</small></div></div></div></section>
<section class="editor-section"><div class="editor-section-title"><span>03</span><div><h3>Galerie et couverture</h3><p>Ajoutez plusieurs visuels, choisissez la couverture, remplacez ou supprimez chaque image.</p></div></div><div class="media-manager" data-media-manager><?php if($productGallery): ?><div class="existing-media-grid"><?php foreach($productGallery as $index=>$image): ?><article class="media-card" data-existing-card><div class="media-preview"><img src="<?= htmlspecialchars($image) ?>" alt="Visuel <?= $index+1 ?>"><span><?= $p['image']===$image?'Couverture':'Image '.($index+1) ?></span></div><label class="cover-choice"><input type="radio" name="cover_existing" value="<?= $index ?>" <?= $p['image']===$image?'checked':'' ?>> <span>Définir comme couverture</span></label><label class="replace-choice">↻ Remplacer cette image<input type="file" name="replace_images[<?= $index ?>]" accept="image/jpeg,image/png,image/webp" data-replace-image></label><label class="delete-choice"><input type="checkbox" name="remove_existing[]" value="<?= $index ?>" data-remove-image> Supprimer</label></article><?php endforeach ?></div><?php else: ?><div class="empty-gallery" data-empty-gallery><span>◇</span><strong>Aucune image actuellement</strong><small>Le produit peut rester sans image.</small></div><?php endif ?><label class="upload-zone modern-upload"><span class="upload-icon">＋</span><div><strong>Ajouter plusieurs images</strong><small>JPG, PNG ou WebP · 6 Mo maximum par image</small></div><input type="file" name="images[]" accept="image/jpeg,image/png,image/webp" multiple data-new-images></label><div class="new-media-grid" data-new-media-grid></div></div></section>
<section class="editor-section digital-product-fields" data-digital-fields><div class="editor-section-title"><span>04</span><div><h3>Fichier numérique protégé</h3><p>Le fichier reste privé et sera transmis via un lien sécurisé.</p></div></div><?php if(!empty($p['digital_file'])): ?><p class="file-ready">✓ Un fichier est déjà prêt. Ajoutez-en un nouveau uniquement pour le remplacer.</p><?php endif ?><div class="field-grid"><label class="full upload-zone modern-upload"><span class="upload-icon">↓</span><div><strong>Choisir le livre ou la ressource</strong><small>PDF, EPUB ou ZIP · 150 Mo maximum</small></div><input type="file" name="digital_file" accept=".pdf,.epub,.zip"></label><label><span class="field-label">Téléchargements autorisés</span><select name="download_limit"><?php foreach([1,3,5,10,20] as $limit): ?><option value="<?= $limit ?>" <?= (int)($p['download_limit']??5)===$limit?'selected':'' ?>><?= $limit ?> téléchargement<?= $limit>1?'s':'' ?></option><?php endforeach ?></select></label></div></section>
<footer class="product-editor-footer"><div><strong><?= $product?'Modification du produit':'Nouveau produit' ?></strong><small>Vérifiez les informations avant l’enregistrement.</small></div><a class="btn secondary" href="/admin/produits">Annuler</a><button class="btn primary">✓ Enregistrer le produit</button></footer></form>
<script>(()=>{const type=document.querySelector('[data-product-type]'),digital=document.querySelector('[data-digital-fields]'),note=document.querySelector('[data-digital-note]'),physical=document.querySelectorAll('[data-physical-field]');const sync=()=>{const isDigital=type.value==='digital';digital.hidden=!isDigital;note.hidden=!isDigital;physical.forEach(field=>field.hidden=isDigital)};type.addEventListener('change',sync);sync();document.querySelectorAll('.modern-upload input:not([data-new-images])').forEach(input=>input.addEventListener('change',()=>{const strong=input.parentElement.querySelector('strong');if(strong&&input.files.length)strong.textContent=input.files.length===1?input.files[0].name:`${input.files.length} fichiers sélectionnés`}));document.querySelectorAll('[data-remove-image]').forEach(box=>box.addEventListener('change',()=>{const card=box.closest('[data-existing-card]'),radio=card.querySelector('input[type=radio]');card.classList.toggle('marked-delete',box.checked);radio.disabled=box.checked}));document.querySelectorAll('[data-replace-image]').forEach(input=>input.addEventListener('change',()=>{if(!input.files[0])return;const img=input.closest('[data-existing-card]').querySelector('img');img.src=URL.createObjectURL(input.files[0])}));const input=document.querySelector('[data-new-images]'),grid=document.querySelector('[data-new-media-grid]');input.addEventListener('change',()=>{grid.innerHTML='';[...input.files].forEach((file,index)=>{const card=document.createElement('article');card.className='media-card new-media-card';card.innerHTML=`<div class="media-preview"><img alt="Nouvelle image"><span>Nouveau</span></div><label class="cover-choice"><input type="radio" name="cover_new" value="${index}"> <span>Définir comme couverture</span></label>`;card.querySelector('img').src=URL.createObjectURL(file);grid.append(card)});input.parentElement.querySelector('strong').textContent=input.files.length?`${input.files.length} nouvelle${input.files.length>1?'s':''} image${input.files.length>1?'s':''}`:'Ajouter plusieurs images'})})();</script>
<style>.product-editor{max-width:980px;border:0;border-radius:22px;box-shadow:0 14px 42px rgba(30,35,60,.07);overflow:hidden}.product-editor [hidden]{display:none!important}.product-editor .editor-section{padding:30px 34px;border-bottom:1px solid #edf0f4}.editor-section-title{display:flex;align-items:flex-start;gap:13px;margin-bottom:24px}.editor-section-title>span{width:34px;height:34px;border-radius:11px;display:grid;place-items:center;flex:none;background:color-mix(in srgb,var(--primary) 11%,white);color:var(--primary);font:800 10px Manrope}.editor-section-title h3{font-size:16px;margin:0 0 3px}.editor-section-title p{font-size:10px;color:var(--muted);margin:0}.product-editor .field-grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}.product-editor .field-grid .full{grid-column:1/-1}.product-editor label{display:flex;flex-direction:column;gap:8px;color:#343b4a}.field-label{font-size:10px;font-weight:750;letter-spacing:.15px}.field-label b{color:#df5555}.product-editor input:not([type=file]),.product-editor select,.product-editor textarea{width:100%;border:1px solid #dfe3ea;background:#fafbfc;border-radius:13px;color:#202737;outline:0;transition:border-color .2s,box-shadow .2s,background .2s}.product-editor input:not([type=file]),.product-editor select{height:50px;padding:0 14px}.product-editor textarea{padding:14px;line-height:1.65;resize:vertical}.product-editor select{appearance:none;padding-right:42px;background-image:linear-gradient(45deg,transparent 50%,#72798a 50%),linear-gradient(135deg,#72798a 50%,transparent 50%);background-position:calc(100% - 19px) 21px,calc(100% - 14px) 21px;background-size:5px 5px,5px 5px;background-repeat:no-repeat}.product-editor input:focus,.product-editor select:focus,.product-editor textarea:focus{border-color:var(--primary);background:#fff;box-shadow:0 0 0 4px color-mix(in srgb,var(--primary) 10%,transparent)}.product-editor input::placeholder,.product-editor textarea::placeholder{color:#a4aab5}.product-editor label>small{font-size:8px;color:#8b92a0;font-weight:500}.input-suffix{position:relative}.input-suffix input{padding-right:64px!important}.input-suffix b{position:absolute;right:12px;top:16px;font-size:8px;color:#858c99;background:#eceef2;border-radius:6px;padding:4px 6px}.modern-upload{position:relative;margin:16px 0 0!important;min-height:92px;padding:18px!important;border:1.5px dashed #cbd1dc!important;border-radius:15px!important;background:#fafbfc;cursor:pointer;transition:.2s;flex-direction:row!important;align-items:center}.modern-upload:hover{border-color:var(--primary)!important;background:color-mix(in srgb,var(--primary) 3%,white)}.modern-upload input{position:absolute;inset:0;width:100%;opacity:0;cursor:pointer}.upload-icon{width:43px;height:43px;border-radius:12px;display:grid;place-items:center;flex:none;background:color-mix(in srgb,var(--primary) 11%,white);color:var(--primary);font-size:20px}.modern-upload strong{font-size:11px}.modern-upload small{margin-top:4px!important}.existing-media-grid,.new-media-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:13px}.new-media-grid{margin-top:13px}.media-card{border:1px solid #e1e5eb;border-radius:16px;padding:9px;background:#fff;transition:.2s}.media-card.marked-delete{opacity:.48;background:#fff3f3;border-color:#efbcbc}.media-preview{position:relative}.media-preview img{display:block;width:100%;height:142px;object-fit:cover;border-radius:11px;background:#eef1f3}.media-preview span{position:absolute;left:7px;bottom:7px;padding:5px 7px;border-radius:7px;background:rgba(20,29,38,.8);color:#fff;font-size:7px;font-weight:800}.media-card label{flex-direction:row;align-items:center;margin-top:8px;font-size:8px;font-weight:700;cursor:pointer}.cover-choice input,.delete-choice input{width:15px!important;height:15px!important}.replace-choice{justify-content:center;padding:8px;border-radius:9px;background:#f1f3f7;color:var(--primary)!important;position:relative;overflow:hidden}.replace-choice input{position:absolute;inset:0;opacity:0;cursor:pointer}.delete-choice{color:#c34545!important}.empty-gallery{display:flex;align-items:center;justify-content:center;flex-direction:column;min-height:130px;border:1px dashed #d8dde5;border-radius:15px;background:#fafbfc;color:#8a919e}.empty-gallery>span{font-size:24px}.empty-gallery strong{font-size:10px}.empty-gallery small{font-size:8px;margin-top:3px}.digital-stock-note{display:flex;align-items:center;gap:12px;background:#ecf8f2;border:1px solid #d2eee0;border-radius:14px;padding:15px}.digital-stock-note>span{width:37px;height:37px;border-radius:10px;display:grid;place-items:center;background:#178359;color:#fff;font-size:18px}.digital-stock-note>div{display:flex;flex-direction:column}.digital-stock-note small{font-size:8px;color:#648076}.file-ready{padding:12px 14px;border-radius:11px;background:#e7f7ef;color:#147550;font-size:9px}.product-editor-footer{display:flex;align-items:center!important;gap:10px;padding:20px 34px!important;background:#fafbfc}.product-editor-footer>div{display:flex;flex:1;flex-direction:column}.product-editor-footer>div strong{font-size:10px}.product-editor-footer>div small{font-size:8px;color:var(--muted)}.product-editor-footer .btn{border-radius:11px;min-height:43px}@media(max-width:700px){.existing-media-grid,.new-media-grid{grid-template-columns:1fr 1fr}}@media(max-width:650px){.product-editor .editor-section{padding:24px 18px}.product-editor .field-grid{grid-template-columns:1fr}.product-editor .field-grid .full{grid-column:auto}.product-editor-footer{padding:16px 18px!important;flex-wrap:wrap}.product-editor-footer>div{width:100%;flex-basis:100%}}@media(max-width:440px){.existing-media-grid,.new-media-grid{grid-template-columns:1fr}}</style>
